const pictHead='<circle cx="50" cy="23" r="12"/>'+pictSmile;
const rigSvg=body=>'<svg class="character-rig" viewBox="0 0 110 90" aria-hidden="true" fill="currentColor">'+body+'</svg>';
const navCharacters={
 home:rigSvg(pictHead+pictTorso+'<g class="reading-arms"><path class="limb" d="M40 47L28 58L30 66M60 47L75 58L73 66"/><g class="reading-paper"><path class="paper-left" d="M27 54L50 58V83L27 79Z"/><path class="paper-right" d="M50 58L76 54V79L50 83Z"/><path class="paper-ink" d="M32 62L44 64M32 69L44 71M56 64L69 62M56 71L69 69"/></g><circle cx="28" cy="65" r="4"/><circle cx="75" cy="65" r="4"/></g>'),
 community:rigSvg('<g class="chat-left" transform="translate(-18 7) scale(.9)">'+pictHead+pictTorso+'<path class="limb" d="M60 47L72 53L79 46"/></g><g class="chat-right" transform="translate(27 7) scale(.9)">'+pictHead+pictTorso+'<path class="limb" d="M40 47L30 58"/></g><g class="chat-dots"><circle cx="46" cy="8" r="2"/><circle cx="54" cy="8" r="2"/><circle cx="62" cy="8" r="2"/></g>'),
 guides:rigSvg(pictHead+pictTorso+'<g class="detective-cap"><path d="M36 14Q38 2 50 2Q62 2 65 14Z"/><path class="tool-line" d="M30 15H70"/></g><g class="inspection-hand"><path class="limb" d="M60 47L75 56L86 48"/><path class="tool-handle" d="M86 49L79 37"/><circle class="lens-ring" cx="73" cy="28" r="13"/><circle cx="86" cy="48" r="4"/></g>'),
 creations:rigSvg(pictHead+pictTorso+'<g class="artist-beret"><path d="M34 15Q27 10 37 5Q54 -2 65 7L62 13L40 17Z"/><path class="tool-line" d="M52 4L56 0"/></g><g class="painting-hand"><path class="limb" d="M60 47L75 59L85 51"/><path class="brush-shaft" d="M80 60L93 32"/><path d="M90 32Q92 25 100 23Q99 34 94 36Z"/><circle cx="85" cy="51" r="4"/></g><path class="limb thinking-arm" d="M40 48L30 44L39 34"/>'),
 deals:rigSvg('<path class="hair-cap" d="M34 34V18Q34 1 50 1Q66 1 66 18V34H61V16Q50 8 39 16V34Z"/><circle cx="50" cy="23" r="11"/>'+pictSmile+'<path d="M39 42Q50 38 61 42L69 77H31Z"/><g class="carrying-hand"><path class="limb" d="M60 47L72 57L82 54"/><path class="bag-handle" d="M76 62Q76 49 83 49Q90 49 90 62"/><path class="bag-body" d="M71 61H96L94 83H73Z"/><circle cx="82" cy="54" r="4"/></g><path class="limb" d="M39 47L29 62"/>')
};
