const licensedFigure=kind=>`<span class="licensed-pictogram figure-${kind}" style="--figure:url('/pictogram-${kind}.png')" aria-hidden="true"></span>`;
Object.keys(navCharacters).forEach(kind=>navCharacters[kind]=licensedFigure(kind));
for(const s of ['#brand-man','#rail-man','#art-figure','#portal-man-a','#portal-man-b'])$(s).innerHTML=manSVG;document.querySelectorAll('.nav-item').forEach(b=>{const kind=b.dataset.route;const art=navCharacters[kind]||manSVG;b.insertAdjacentHTML('afterbegin',`<span class="nav-character nav-${kind}">${art}</span><span class="nav-label">${b.textContent.trim()}</span>`);[...b.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE).forEach(n=>n.remove())});document.querySelector('footer>div').prepend($('#motion-toggle'));
const games=['SNAPTIC','以撒的结合','Minecraft','绝地潜兵 2','赛博朋克 2077'];const roles={guest:'游客',player:'普通玩家',moderator:'版主',admin:'管理员'};
const seeds=[
['p1','SNAPTIC','讨论','离线之后，朋友还会记得我们吗？','小离','li','刚打开这个数字世界，就想起了早年聊天软件里的头像。\n\n这是一条讨论示例：你有没有一款让你想起旧朋友的游戏？可以在下方留下自己的真实想法。','怀旧'],
['p2','以撒的结合','攻略','新手存档：第一轮先别急着拿所有道具','韩宜恒','hyh','这是一份攻略结构示例。\n\n1. 先观察房间布局，再决定移动路线。\n2. 不熟悉的道具先查询作用，避免盲目组合。\n3. 把一次失败当成下一次路线的笔记。\n\n正式攻略应在实际游玩验证后补充道具名称与来源。','新手'],
['p3','Minecraft','资源','给方块世界加一点胶片颗粒','模组搬运工','modder','资源提交示例\n\n资源类型：画面风格介绍\n适配版本：待作者实际验证\n下载地址：本示例未提供文件\n来源与授权：正式上传时填写作者及许可\n\n不要用未知文件覆盖自己的存档。','MOD'],
['p4','绝地潜兵 2','讨论','民主需要你，但也需要一位靠谱的撤离队友','版主小白','white','今天的讨论主题是合作。\n\n你最想对临时队友说的一句话是什么？\n这是一条示例帖，不代表实际组队招募。','联机'],
['p5','Minecraft','作品','地铁末班存档：把方块夜色做成一张海报','小离','li','作品展示布局示例。\n\n画面设想：深灰底色、蓝紫光源、一条通向车站的路。\n媒介：截图与平面排版。\n作者说明：正式作品需由上传者提供，并注明原图出处。','海报'],
['p6','SNAPTIC','攻略','记忆空间探索笔记：给第一次迷路的玩家','小离','li','本条用于展示攻略的阅读、搜索、收藏和评论流程。\n\n正文可以按场景、目标、操作步骤和易错点组织。暂不将未经验证的玩法写成确定攻略。','探索'],
['p7','赛博朋克 2077','作品','夜之城不睡，我们也只是再截一张图','韩宜恒','hyh','摄影作品介绍示例。\n\n作品的标题、所属游戏、创作说明和版权来源应一起展示。\n现在先试试收藏和评论功能。','摄影'],
['p8','以撒的结合','求助','“再来一局”之后，怎样整理自己的失败路线？','模组搬运工','modder','求助帖示例。\n\n可以说明游戏版本、操作环境、已经尝试的方法，再附上实际截图。信息完整时，队友更容易帮忙。','经验'],
['p9','SNAPTIC','作品','出口小人旅行日志 / 紫色传送门','小离','li','作品故事示例：一个小人搬开窗口，另一个从传送门里递来新的存档。\n\n当前网站中的平面小人和小场景为本项目原创绘制。','动画']
];
const initial=()=>({version:3,actor:'hyh',interests:['SNAPTIC','以撒的结合','Minecraft'],saved:[],posts:seeds.map((p,i)=>({id:p[0],game:p[1],type:p[2],title:p[3],author:p[4],user:p[5],body:p[6],tag:p[7],sample:true,date:'示例内容',rank:10-i,deleted:false,flagged:false})),users:[{id:'hyh',name:'韩宜恒',role:'player',status:'active'},{id:'li',name:'小离',role:'player',status:'active'},{id:'modder',name:'模组搬运工',role:'player',status:'active'},{id:'white',name:'版主小白',role:'moderator',status:'active'},{id:'admin',name:'站务管理员',role:'admin',status:'active'}],comments:[{id:'c1',post:'p1',user:'li',text:'示例评论：旧存档里，也有一段关于朋友的记忆。',date:'示例对话'}],chat:[{id:'m1',channel:'lobby',user:'li',text:'示例对话：欢迎回来，存档还在。',date:'示例消息'},{id:'m2',channel:'help',user:'white',text:'示例对话：提问时可以补充版本和截图。',date:'示例消息'}],audit:[],wikiState:{}});
let db=initial();try{const d=JSON.parse(localStorage.getItem('offline-forum-v3')||'null');if(d&&d.version===3&&Array.isArray(d.posts)&&Array.isArray(d.users)&&Array.isArray(d.comments)&&Array.isArray(d.chat)&&Array.isArray(d.saved)&&Array.isArray(d.interests)&&Array.isArray(d.audit))db=d}catch{};
db.wikiState=db.wikiState&&typeof db.wikiState==='object'?db.wikiState:{};
let route='home',gameFilter='',typeFilter='全部',sort='recommended',busy=false,pending=null,channel='lobby',adminTab='content',searchType='all',motionPaused=matchMedia('(prefers-reduced-motion:reduce)').matches;const reduced=matchMedia('(prefers-reduced-motion:reduce)');
const actor=()=>window.coreUser||{id:'guest',name:'访客',role:'guest',status:'active'},canManage=()=>['admin','moderator'].includes(actor().role)&&actor().status==='active',canAdmin=()=>actor().role==='admin'&&actor().status==='active';
function save(){try{localStorage.setItem('offline-forum-v3',JSON.stringify(db))}catch{toast('浏览器无法保存，当前操作仅在本次访问有效')}updateChrome()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function name(id){return db.users.find(u=>u.id===id)?.name||'玩家'}function timestamp(){return new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}function id(prefix){return prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}function audit(action){db.audit.unshift({actor:actor().name,action,date:timestamp()});db.audit=db.audit.slice(0,80)}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;const d=$('#common-dialog');if(!d.open)d.showModal()}
function updateChrome(){const a=actor();$('#identity-name').textContent=a.name;$('#role-label').textContent=(roles[a.role]||'普通玩家')+(a.flair?' · '+a.flair:'');$('#saved-count').textContent=window.coreSavedCount||0;$('.admin-link').hidden=!canManage();$('#game-links').innerHTML='<button class="rail-link" data-go="profile">◉ 我的玩家主页</button><button class="rail-link" data-go="wiki">⌕ 百科与官方资料</button><button class="rail-link" onclick="openOfflineRoom()">↻ 360° 游戏环廊</button>';window.updatePlayerHeader?.();document.documentElement.classList.toggle('motion-paused',motionPaused||reduced.matches);$('#motion-toggle').setAttribute('aria-pressed',motionPaused);$('#motion-toggle').textContent=motionPaused?'▷':'Ⅱ'}
function head(title,sub,action=''){return`<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(sub)}</p></div>${action||'<span class="date-chip">'+new Date().toLocaleDateString('zh-CN')+' / 玩家频道</span>'}</div>`}
function published(){return window.corePosts||[]}function ordered(list){return[...list].sort((a,b)=>sort==='latest'?b.id.localeCompare(a.id):sort==='active'?db.comments.filter(c=>c.post===b.id).length-db.comments.filter(c=>c.post===a.id).length:(Number(db.interests.includes(b.game))-Number(db.interests.includes(a.game)))||b.rank-a.rank)}
function newsRoute(n){return n.appid?'news/steam/'+n.appid+'/'+n.id:'news/community/'+n.url.match(/articles\/(\d+)/)?.[1]}
function sourceTime(value){return value?new Date(value).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):''}
function imageBlock(item,classes='',priority=false){if(!item?.image)return '<div class="live-image '+classes+'"><span>来源暂未提供图片</span></div>';return '<div class="live-image '+classes+'"><img src="/api/media?url='+encodeURIComponent(item.image)+'" data-original-image="'+e(item.image)+'" data-fallback-appid="'+e(item.appid||'')+'" alt="'+e(item.game)+' · '+(item.imageKind==='article'?'公告原图':item.imageKind==='source'?'资讯原图':'游戏官方宣传图')+'" loading="'+(priority?'eager':'lazy')+'" decoding="async" referrerpolicy="no-referrer"><span class="image-label">'+(item.imageKind==='article'?'公告原图':item.imageKind==='source'?'资讯原图':'游戏宣传图')+'</span></div>'}
function liveEmpty(kind){const state=SNAPSHOT[kind+'Status'];return '<div class="live-empty" role="status">'+(state==='loading'?'正在连接'+(kind==='community'?'机核资讯来源，获取最新动态与配图':kind==='news'?' Steam，获取最新公告与配图':' Steam，获取国区价格与游戏封面')+'…':state==='error'?'暂时无法连接来源。请重新获取，或前往原始来源查看。':'来源当前没有返回可展示的内容。')+'</div>'}
function liveToolbar(kind){const loading=SNAPSHOT[kind+'Status']==='loading';const providers=SNAPSHOT[kind+'Providers']||[];const failed=providers.filter(p=>p.status!=='ok');return '<div class="live-toolbar"><span>'+ (loading?'正在获取来源数据…':SNAPSHOT[kind+'At']?'本次获取 '+sourceTime(SNAPSHOT[kind+'At'])+' · 北京时间':'尚未获取数据')+(failed.length?' · '+failed.length+' 个来源暂不可用':'')+'</span><button class="small-btn" data-live-refresh="'+kind+'" '+(loading?'disabled':'')+'>↻ 重新获取</button></div>'}
function dealCards(limit=12){return liveToolbar('deals')+(SNAPSHOT.deals.length?'<div class="deal-grid">'+SNAPSHOT.deals.slice(0,limit).map(d=>'<a class="deal-card" href="'+e(d.url)+'" target="_blank" rel="noopener">'+imageBlock(d,'deal-cover')+'<div class="deal-copy"><span class="deal-store">STEAM / 国区 · CNY</span><h3>'+e(d.game)+'</h3><div class="deal-buy"><span class="deal-off">'+(d.discount?'-'+e(d.discount)+'%':'当前原价')+'</span><div class="deal-price">'+(d.original?'<s>'+e(d.original)+'</s>':'')+e(d.price)+'</div></div>'+(d.expiresAt?'<p class="deal-expiry">优惠截止 '+e(new Date(d.expiresAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))+'</p>':'')+'</div></a>').join('')+'</div><p class="price-note">价格来自本次 Steam 接口响应；实际购买价格与活动期限以商店为准。</p>':liveEmpty('deals'))}
function quickPosts(){return`<div class="quick-posts">${ordered(published()).slice(0,3).map(p=>`<a href="#article/${p.id}" data-go="article/${p.id}" class="quick-post"><span><span class="game-tag">${e(p.game)}</span>${e(p.title)}</span><small>打开存档 ↗</small></a>`).join('')}</div>`}
function communityNews(){return '<div class="section-title"><h2>社区与行业动态</h2><span>来自机核公开资讯</span></div><p class="community-source-note">新作发布、重大更新与玩家社区动态。按来源发布时间排列，不虚构热度。</p>'+liveToolbar('community')+(SNAPSHOT.community.length?'<div class="news-list">'+SNAPSHOT.community.slice(0,6).map(n=>'<a class="news-row" href="#'+newsRoute(n)+'" data-go="'+newsRoute(n)+'">'+imageBlock(n,'news-thumbnail')+'<div class="news-row-copy"><span class="eyebrow">'+e(n.source)+'</span><h3>'+e(n.title)+'</h3><small>'+e(n.date)+' · '+e(n.author)+'</small></div></a>').join('')+'</div>':liveEmpty('community'))}
let discoveryTab='recommended';
function newsRows(list){return '<div class="news-list">'+list.map(n=>'<a class="news-row" href="#'+newsRoute(n)+'" data-go="'+newsRoute(n)+'">'+imageBlock(n,'news-thumbnail')+'<div class="news-row-copy"><span class="eyebrow">'+e(n.game||n.source)+'</span><h3>'+e(n.title)+'</h3><small>'+e(n.date)+' · '+e(n.source)+'</small></div></a>').join('')+'</div>'}
function homeView(){const tabs={recommended:'为你发现',official:'官方公告',community:'社区与行业',deals:'折扣补给'};let content='';if(discoveryTab==='community')content=communityNews();else if(discoveryTab==='deals')content='<p class="community-source-note">特惠精选；游戏雷达支持热销、促销、搜索和翻页。</p>'+dealCards(12)+'<button class="solid-btn" data-go="deals">打开全部游戏雷达 →</button>';else {let list=SNAPSHOT.news;if(discoveryTab==='recommended')list=[...list].sort((a,b)=>(a.recommendOrder??99)-(b.recommendOrder??99));const n=list[0];content='<p class="community-source-note">'+e(window.newsRecommendationNote||'未绑定 Steam 时，从本次可用游戏中随机探索。')+'</p>'+liveToolbar('news')+(n?'<section class="news-feature"><a class="feature-art news-cover" href="#'+newsRoute(n)+'" data-go="'+newsRoute(n)+'">'+imageBlock(n,'',true)+'</a><div class="feature-copy"><span class="eyebrow">'+e(n.game)+' / 官方公告</span><h2>'+e(n.title)+'</h2><p>'+e(n.date)+' · '+e(n.source)+'</p><a href="#'+newsRoute(n)+'" data-go="'+newsRoute(n)+'">站内阅读公告 →</a></div></section>'+newsRows(list.slice(1,discoveryTab==='official'?40:16)):liveEmpty('news'));}
return head('今天值得关注','先选一个频道，再慢慢翻。资讯保留来源与发布时间。')+'<div class="discovery-tabs" role="group" aria-label="资讯分类">'+Object.entries(tabs).map(([k,v])=>'<button data-discovery-tab="'+k+'" aria-pressed="'+(discoveryTab===k)+'">'+v+'</button>').join('')+'</div>'+content;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-discovery-tab]');if(button){discoveryTab=button.dataset.discoveryTab;render('home',false)}});

function forumView(kind){let list=published();let title='玩家社区',desc='按你关注的游戏推荐，像论坛一样慢慢聊。';if(kind==='guides'){list=list.filter(p=>['攻略','资源'].includes(p.type));title='攻略与资源';desc='出发前翻一翻，让下一次“再来一局”少走一点弯路。'}if(kind==='creations'){list=list.filter(p=>p.type==='作品');title='玩家二创';desc='截图、海报、动画和模组。通关之后，故事还在继续。'}if(kind==='saved'){list=list.filter(p=>db.saved.includes(p.id));title='我的收藏';desc='这些存档，值得下次再回来看看。'}if(gameFilter)list=list.filter(p=>p.game===gameFilter);if(typeFilter!=='全部')list=list.filter(p=>p.type===typeFilter);list=ordered(list);let types=kind==='guides'?['全部','攻略','资源']:kind==='creations'?['全部','作品']:['全部','讨论','求助','攻略','资源','作品'];return head(title,desc,`<button class="solid-btn" data-action="publish">＋ 发布${kind==='creations'?'作品':'帖子'}</button>`)+`<div class="feed-tools">${types.map(t=>`<button class="filter-chip ${typeFilter===t?'active':''}" data-filter="${e(t)}">${e(t)}</button>`).join('')}${gameFilter?`<button class="filter-chip active" data-clear-game>${e(gameFilter)} ×</button>`:''}<select id="sort-select" aria-label="帖子排序"><option value="recommended" ${sort==='recommended'?'selected':''}>为你推荐</option><option value="latest" ${sort==='latest'?'selected':''}>最近发布</option><option value="active" ${sort==='active'?'selected':''}>评论活跃</option></select></div><table class="forum-table"><thead><tr><th>主题 / 游戏</th><th>回复</th><th>发布者</th><th>收藏</th></tr></thead><tbody>${list.map(p=>`<tr data-post-row="${p.id}"><td><a class="thread-title" data-go="article/${p.id}" href="#article/${p.id}"><span class="thread-badge">[${e(p.type)}]</span>${e(p.title)}${p.flagged?'<span class="flagged-tag">待核验</span>':''}</a><div class="thread-meta"><span class="game-tag">${e(p.game)}</span>${e(p.tag)}${p.sample?'<span class="thread-demo">示例帖</span>':' · '+e(p.date)}</div></td><td class="thread-count">${db.comments.filter(c=>c.post===p.id).length}</td><td><span class="table-avatar"><i class="avatar">${e(name(p.user).slice(0,1))}</i>${e(name(p.user))}</span></td><td><button class="subtle-btn" data-save="${p.id}" aria-label="${db.saved.includes(p.id)?'取消收藏':'收藏'} ${e(p.title)}" aria-pressed="${db.saved.includes(p.id)}">${db.saved.includes(p.id)?'◆':'◇'}</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<p class="empty">这里暂时没有内容。换一个分类，或者保存一份新存档。</p>'}`}
const wiki=[{id:'w1',title:'SNAPTIC / 数字空间',game:'SNAPTIC',body:'SNAPTIC 是发生在离线电脑里的物理解谜平台游戏。官方介绍提到磁化、弹珠变形以及旧缓存、聊天记录等线索。\n\n本页面收录基础资料，玩法细节请查阅官方介绍。',source:'https://store.steampowered.com/app/5201040/SNAPTIC/'},{id:'w2',title:'攻略、资源与二创的区别',game:'站内指南',body:'攻略用于解释玩法步骤。资源条目介绍文件、版本和来源。二创展示玩家的作品与创作过程。\n\n资料上传时请提供作者、适配版本和来源链接。'},{id:'w3',title:'如何整理一次游戏求助',game:'站内指南',body:'描述游戏名、版本、遇到的问题与已经尝试过的办法。\n\n附上实际报错或截图，避免分享密码、令牌和私人账户信息。'},{id:'w4',title:'评论与社区身份',game:'站内指南',body:'普通玩家可以发帖、发表评论和收藏。版主可以标记资料、移除违规内容。管理员还可以管理用户身份与状态。\n\n当前原型的身份切换与管理只用于本机演示，正式权限应在服务端校验。'}];
function publicWikis(){return wiki.filter(w=>!db.wikiState[w.id]?.deleted).map(w=>({...w,...db.wikiState[w.id]}))}
function managementEntry(key){if(key.startsWith('wiki/')){const w=wiki.find(w=>w.id===key.slice(5));if(!w)return null;const state=db.wikiState[w.id]||(db.wikiState[w.id]={});state.title=w.title;return state}return db.posts.find(p=>p.id===key)}
function managementItems(){return[...db.posts,...wiki.map(w=>({...w,...db.wikiState[w.id],id:'wiki/'+w.id,type:'百科'}))]}
function wikiView(){return head('站内百科','从游戏资料到社区使用说明，像整理 Wiki 一样整理我们的存档。',`<button class="small-btn" data-action="search">⌕ 搜索资料</button>`)+`<div class="wiki-cards">${publicWikis().map(w=>`<a class="wiki-card" href="#wiki/${w.id}" data-go="wiki/${w.id}"><h3>${e(w.title)}${w.flagged?'<span class="flagged-tag">待核验</span>':''}</h3><p>${e(w.body.slice(0,85))}…</p></a>`).join('')}</div>`}
function articleView(pid,isWiki=false){const p=isWiki?publicWikis().find(w=>w.id===pid):db.posts.find(p=>p.id===pid&&!p.deleted);if(!p)return head('这份存档暂时不在这里','内容可能已被移除，试试全站搜索。')+`<button class="small-btn" data-go="community">返回社区</button>`;const comments=db.comments.filter(c=>c.post===(isWiki?'wiki/'+pid:pid)),key=isWiki?'wiki/'+pid:pid;return`<button class="subtle-btn" data-go="${isWiki?'wiki':p.type==='作品'?'creations':['攻略','资源'].includes(p.type)?'guides':'community'}">← 返回${isWiki?'百科':'列表'}</button><article class="article"><span class="game-tag">${e(p.game)}</span>${p.flagged?'<span class="flagged-tag">待核验</span>':''}<h1>${e(p.title)}</h1><div class="article-meta">${isWiki?'基础资料':e(name(p.user))+' · '+e(p.date)+(p.sample?' · 内容示例':'')}</div><div class="article-body">${e(p.body)}</div>${p.source?`<p><a class="subtle-btn" href="${e(p.source)}" target="_blank" rel="noopener">官方资料来源 ↗</a></p>`:''}<div class="article-actions">${isWiki?'':`<button class="small-btn" data-save="${pid}">${db.saved.includes(pid)?'◆ 已收藏':'◇ 收藏存档'}</button>`}${canManage()?`<button class="small-btn" data-flag="${key}">${p.flagged?'取消标记':'标记待核验'}</button><button class="small-btn danger" data-delete="${key}">移除内容</button>`:''}</div></article><section class="comment-section"><h2>评论区 <span class="muted">${comments.length}</span></h2>${comments.map(c=>`<div class="comment"><i class="avatar">${e(name(c.user).slice(0,1))}</i><div class="comment-text"><span class="name">${e(name(c.user))}</span><p>${e(c.text)}</p><small>${e(c.date)}</small></div>${canManage()||c.user===actor().id?`<button class="comment-delete" data-comment-delete="${c.id}">删除</button>`:''}</div>`).join('')}${comments.length?'':'<p class="empty">第一条评论，就从你开始。别忘了给剧透留一点距离。</p>'}<form class="comment-form" data-comment-form="${e(key)}"><label class="sr-only" for="comment-input">发表评论</label><textarea id="comment-input" placeholder="分享经验，或者给下一位玩家一句提示…" maxlength="2000" required></textarea><div class="form-tail"><span>以 ${e(actor().name)} 的身份发言</span><button class="solid-btn" type="submit" ${actor().status!=='active'?'disabled':''}>发表评论</button></div></form></section>`}
function adminView(){if(!canManage())return head('这里是站务区','当前身份没有管理权限。')+`<button class="small-btn" data-action="identity">切换体验身份</button>`;const content=`<table class="admin-table"><thead><tr><th>资料标题</th><th>状态</th><th>操作</th></tr></thead><tbody>${managementItems().map(p=>`<tr data-admin-post="${p.id}"><td>${e(p.title)}<br><small class="muted">${e(p.game)} / ${e(p.type)}</small></td><td>${p.deleted?'已移除':p.flagged?'待核验':'正常'}</td><td>${p.deleted?`<button data-restore="${p.id}">恢复</button>`:`<button data-flag="${p.id}">${p.flagged?'取消标记':'标记'}</button><button class="danger" data-delete="${p.id}">移除</button>`}</td></tr>`).join('')}</tbody></table>`;const users=canAdmin()?`<table class="admin-table"><thead><tr><th>玩家</th><th>身份</th><th>状态</th></tr></thead><tbody>${db.users.map(u=>`<tr><td>${e(u.name)}${u.id===actor().id?'<small>（当前）</small>':''}</td><td><select data-user-role="${u.id}" aria-label="${e(u.name)} 的身份">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${u.role===k?'selected':''}>${v}</option>`).join('')}</select></td><td><button data-user-status="${u.id}" ${u.id===actor().id?'disabled':''}>${u.status==='active'?'禁言':'解除禁言'}</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">身份管理仅供管理员使用，版主可管理内容。</p>';return head('社区管理台','本机管理演示：标记、移除、恢复资料，管理身份与查看操作记录。')+`<div class="admin-tabs"><button data-admin-tab="content" class="${adminTab==='content'?'active':''}">内容管理</button><button data-admin-tab="users" class="${adminTab==='users'?'active':''}" ${!canAdmin()?'disabled':''}>用户身份</button><button data-admin-tab="audit" class="${adminTab==='audit'?'active':''}">操作记录</button></div>`+(adminTab==='users'?users:adminTab==='audit'?db.audit.map(a=>`<div class="audit-row">${e(a.actor)} · ${e(a.action)}<small>${e(a.date)}</small></div>`).join('')||'<p class="empty">暂无管理操作。</p>':content)}
function prepareRouteEffects(r,animate=true){document.body.dataset.visualRoute=r;document.querySelectorAll('.integrated-art-host').forEach(el=>el.remove());if(window.mountRouteArt)window.mountRouteArt();applyReactBitsEffects($('#page-pane'),animate)}
function decryptHeading(root){const heading=root.querySelector('.page-heading h1');if(!heading||motionPaused||reduced.matches)return;const final=heading.textContent,chars='01▓▒░◇△';let tick=0;const timer=setInterval(()=>{heading.textContent=[...final].map((char,index)=>char===' '?char:index<tick/2?char:chars[(index+tick)%chars.length]).join('');tick++;if(tick>final.length*2){clearInterval(timer);heading.textContent=final}},28)}
function applyReactBitsEffects(root,animate=true){root.querySelectorAll('.news-feature,.deal-card,.wiki-card').forEach(card=>{card.classList.add('spotlight-card');card.onpointermove=ev=>{const b=card.getBoundingClientRect();card.style.setProperty('--spot-x',ev.clientX-b.left+'px');card.style.setProperty('--spot-y',ev.clientY-b.top+'px')}});root.querySelectorAll('.deal-card').forEach(card=>card.classList.add('glare-hover'));root.querySelectorAll('.solid-btn').forEach(button=>button.classList.add('star-border'));root.querySelectorAll('.forum-table tbody tr,.news-row,.quick-post,.wiki-card').forEach((item,index)=>{if(animate&&!motionPaused&&!reduced.matches)item.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,delay:Math.min(index*45,360),easing:'cubic-bezier(.2,.8,.2,1)',fill:'both'})});if(animate)decryptHeading(root)}
function render(r=route,animate=true){if(typeof window.unmountCommunity==='function')window.unmountCommunity();route=r;let html;if(r==='home')html=homeView();else if(['community','guides','creations','saved'].includes(r))html=forumView(r);else if(r==='deals')html=typeof catalogView==='function'?catalogView():head('游戏折扣','愿望单还在等，但购买前也可以先等等。')+dealCards()+`<div class="section-title"><h2>买之前，先翻一份攻略</h2></div>${quickPosts()}`;else if(r.startsWith('news/'))html=typeof newsReader==='function'?newsReader(r):head('正在打开新闻','正在连接来源…');else if(r==='wiki')html=wikiView();else if(r.startsWith('wiki/'))html=articleView(r.slice(5),true);else if(r.startsWith('article/'))html=articleView(r.slice(8));else if(r==='admin')html=adminView();else html=head('走错传送门了','返回发现页，重新选择一份存档。');const coreRoute=['community','guides','creations','saved','admin','wiki','minigame','memory','dodge','video'].includes(r)||r.startsWith('video/')||r.startsWith('article/')||r.startsWith('profile')||r.startsWith('wiki/');if(coreRoute&&window.mountCommunity)html='<div id="community-app"></div>';$('#page-pane').innerHTML=html;document.querySelectorAll('.nav-item').forEach(b=>{const yes=b.dataset.route===r||r.startsWith('article/')&&b.dataset.route==='community'||r.startsWith('news/')&&b.dataset.route==='home';b.classList.toggle('active',yes);if(yes)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});prepareRouteEffects(r,animate);updateChrome();attachMagnet();if(typeof mountDiscovery==='function')mountDiscovery(r);if(coreRoute&&window.mountCommunity)window.mountCommunity(r);}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
window.addEventListener('offline-navigate',event=>go(event.detail,false));
function transitionMarkup(kind,target){
 if(kind==='computer')return `<div class="scene-grid"></div><div class="computer-scene revised-workstation"><div class="workstation pictogram-work">${licensedFigure('guides')}<i class="typing-pixels"></i><span class="typing-status">READING YOUR NEXT SAVE…</span></div></div><div class="transition-caption"><strong>正在打开攻略工作台</strong><span>敲完这一行，马上出发。</span></div>`;
 if(kind==='newspaper')return `<div class="scene-grid"></div><div class="newspaper-scene"><span class="themed-actor">${navCharacters.home}</span><div class="paper-fold"><i></i><b></b><em></em></div></div><div class="transition-caption"><strong>正在翻到今天这一版</strong><span>先看头条，再决定去哪张地图。</span></div>`;
 if(kind==='chat')return `<div class="scene-grid"></div><div class="chat-scene"><span class="themed-actor">${navCharacters.community}</span><i class="chat-orb one">GG</i><i class="chat-orb two">?</i><i class="chat-orb three">…</i></div><div class="transition-caption"><strong>玩家频道已接通</strong><span>两个人的存档开始同步。</span></div>`;
 if(kind==='detective')return `<div class="scene-grid"></div><div class="detective-scene"><span class="themed-actor">${navCharacters.guides}</span><div class="transition-lens"><i></i></div><div class="clue a">攻略</div><div class="clue b">资源</div><div class="clue c">Wiki</div></div><div class="transition-caption"><strong>放大线索</strong><span>答案藏在下一页。</span></div>`;
 if(kind==='paint')return `<div class="scene-grid"></div><div class="paint-scene"><span class="themed-actor">${navCharacters.creations}</span><div class="paint-canvas"><i class="stroke a"></i><i class="stroke b"></i><i class="stroke c"></i></div></div><div class="pixel-swap">${Array.from({length:48},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</div><div class="transition-caption"><strong>正在给空白画布上色</strong><span>灵感加载中。</span></div>`;
 if(kind==='shop')return `<div class="scene-grid"></div><div class="shop-scene"><span class="themed-actor">${navCharacters.deals}</span><div class="price-ticket"><b>-70%</b><span>愿望单提醒</span></div><i class="shop-bag one"></i><i class="shop-bag two"></i></div><div class="transition-caption"><strong>正在检查愿望单</strong><span>折扣很快，钱包冷静。</span></div>`;
 return `<div class="push-scene"><div class="pushed-page"><div class="paper-bar"></div><div class="paper-lines"></div></div><span class="scene-actor bracing">${pushManSVG}</span></div><div class="transition-caption"><strong>正在给下一页腾位置</strong><span>这扇门有点重。</span></div>`;
}
async function go(r,animate=true){
 if(!r||r===route)return;
 if(r.startsWith('news/'))animate=false;
 if(busy){pending=r;return}
 if(r==='admin'&&!canManage()){toast('当前身份没有管理权限');return}
 if(!animate||motionPaused||reduced.matches){render(r);history.pushState(null,'','#'+r);if(r.startsWith('news/'))scrollTo(0,0);return}
 busy=true;pending=null;
 const trans=$('#inline-transition'),pane=$('#page-pane');
 const kind=r==='home'?'newspaper':r==='community'?'chat':r==='guides'||r==='wiki'||r.startsWith('wiki/')||r==='admin'||r.startsWith('article/')?'computer':r==='creations'?'paint':r==='deals'?'shop':'push';
 const animations=[];
 const anim=(el,keyframes,options)=>{const instance=el.animate(keyframes,options);animations.push(instance);return instance.finished.catch(()=>{})};
 trans.className='inline-transition scene-transition '+kind+'-transition';
 trans.dataset.kind=kind;
 trans.innerHTML=transitionMarkup(kind,r);
 trans.hidden=false;
 document.body.classList.add('is-scene-transitioning');
 $('#view-host').classList.add('is-transitioning');
 pane.setAttribute('aria-busy','true');
 try{
  await anim(trans,[{opacity:0},{opacity:1}],{duration:kind==='computer'?600:320,easing:'ease-out',fill:'forwards'});
  if(kind==='computer'){
   await wait(1650);
   const monitor=trans.querySelector('.workstation');
   monitor.classList.add('screen-ready');
   await wait(300);
   await anim(monitor,[{transform:'scale(1)',offset:0},{transform:'scale(1.22)',offset:.35},{transform:'scale(13)',offset:1}],{duration:1050,easing:'cubic-bezier(.4,.05,.45,1)',fill:'forwards'});
  }else if(kind==='detective'){
   await wait(820);
   await anim(trans.querySelector('.transition-lens'),[{transform:'scale(1)'},{transform:'scale(13)'}],{duration:520,easing:'cubic-bezier(.5,.05,.8,.2)',fill:'forwards'});
  }else if(kind==='push'){
   await wait(220);
   await Promise.all([
    anim(trans.querySelector('.push-scene'),[{transform:'translateX(-2vw)'},{transform:'translateX(112vw)'}],{duration:1100,easing:'cubic-bezier(.54,.02,.3,1)',fill:'forwards'}),
    anim(pane,[{opacity:1,transform:'translateX(0)'},{opacity:.08,transform:'translateX(100vw)'}],{duration:1050,easing:'cubic-bezier(.54,.02,.3,1)',fill:'forwards'})
   ]);
  }else{
   await Promise.all([anim(pane,[{opacity:1},{opacity:.12}],{duration:360,fill:'forwards'}),wait(kind==='paint'?1320:kind==='shop'?1200:1150)]);
  }
  const next=pending||r;pending=null;
  render(next);history.pushState(null,'','#'+next);
  await Promise.all([
   anim(trans,[{opacity:1},{opacity:0}],{duration:430,easing:'ease-out',fill:'forwards'}),
   anim(pane,[{opacity:.12,transform:'translateY(18px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:560,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'})
  ]);
 }finally{
  animations.forEach(a=>a.cancel());
  trans.hidden=true;
  trans.innerHTML='';
  document.body.classList.remove('is-scene-transitioning');
  $('#view-host').classList.remove('is-transitioning');
  pane.removeAttribute('aria-busy');
  busy=false;
  if(pending){const next=pending;pending=null;go(next)}
 }
}
function openPreferences(){modal('选择你关注的游戏',`<p class="form-tip">你的选择会改变社区与首页推荐的顺序。</p><form id="preferences-form"><div class="choice-grid">${games.map(g=>`<label class="choice"><input type="checkbox" name="game" value="${e(g)}" ${db.interests.includes(g)?'checked':''}>${e(g)}</label>`).join('')}</div><button class="solid-btn" type="submit">保存兴趣</button></form>`)}function openIdentity(){modal('体验不同社区身份',`<p class="form-tip">仅切换本机演示身份，不是真实登录。普通玩家、版主和管理员有不同的操作入口。</p><div class="wiki-cards">${db.users.map(u=>`<button class="wiki-card" data-actor="${u.id}" style="text-align:left"><h3>${e(u.name)} <span class="game-tag">${roles[u.role]}</span></h3><p>${u.status==='active'?'正常发言':'已禁言'}${u.id===actor().id?' · 当前身份':''}</p></button>`).join('')}</div>`)}
function openPublish(){if(actor().status!=='active'){toast('当前身份已被禁言');return}modal(route==='creations'?'发布作品':'发布一份新存档',`<form id="publish-form"><label class="field">标题<input name="title" maxlength="120" required placeholder="给这份存档起个名字"></label><label class="field">所属游戏<select name="game">${games.map(g=>`<option>${e(g)}</option>`).join('')}</select></label><label class="field">分类<select name="type">${['讨论','求助','攻略','资源','作品'].map(t=>`<option ${route==='creations'&&t==='作品'||route==='guides'&&t==='攻略'?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">正文<textarea name="body" maxlength="10000" required placeholder="写下经验、作品说明或资料来源…"></textarea></label><p class="form-tip">本轮保存文字内容；图片和文件上传将在正式系统接入。</p><button class="solid-btn" type="submit">发布到本机社区</button></form>`)}
function toggleSave(pid){const p=db.posts.find(p=>p.id===pid&&!p.deleted);if(!p)return;db.saved=db.saved.includes(pid)?db.saved.filter(k=>k!==pid):[...db.saved,pid];save();render();toast(db.saved.includes(pid)?'这份存档已加入收藏':'已取消收藏')}
function flag(pid){if(!canManage()){toast('需要版主或管理员身份');return}const p=managementEntry(pid);if(!p||p.deleted)return;p.flagged=!p.flagged;audit((p.flagged?'标记待核验：':'取消标记：')+p.title);save();render()}
function removePost(pid){if(!canManage())return;const p=managementEntry(pid);if(!p)return;modal('移除这份资料？',`<p class="form-tip">${e(p.title)}<br>移除后不再出现在列表与搜索中，可以在管理台恢复。</p><button class="small-btn danger" data-confirm-delete="${pid}">确认移除</button>`)}
function openSearch(wikiOnly=false){searchType=wikiOnly?'wiki':'all';$('#site-query').value='';$('#search-dialog').showModal();$('#site-query').focus();renderSearch()}
function renderSearch(){let q=$('#site-query').value.trim().toLowerCase(),items=[];if(['all','wiki'].includes(searchType))items.push(...publicWikis().map(w=>({type:'百科',title:w.title,text:w.game+' '+w.body,route:'wiki/'+w.id})));if(['all','posts'].includes(searchType))items.push(...published().map(p=>({type:p.type,title:p.title,text:p.game+' '+p.body,route:'article/'+p.id})));if(['all','users'].includes(searchType))items.push(...(window.coreUser?[window.coreUser]:[]).map(u=>({type:'玩家',title:u.name,text:roles[u.role],user:u.id})));if(['all','news'].includes(searchType))items.push(...SNAPSHOT.news.map(n=>({type:'新闻',title:n.title,text:n.game+' '+n.date,url:n.url})));if(q)items=items.filter(i=>(i.title+' '+i.text).toLowerCase().includes(q));else items=items.slice(0,7);$('#search-results').innerHTML=items.length?items.map(i=>i.url?`<a class="search-result" href="${e(i.url)}" target="_blank" rel="noopener"><strong>${e(i.title)}</strong><p>${e(i.text.slice(0,75))}</p><small>${i.type} · 官方来源 ↗</small></a>`:`<button class="search-result" ${i.route?'data-search-go="'+e(i.route)+'"':'data-search-user="'+e(i.user)+'"'}><strong>${e(i.title)}</strong><p>${e(i.text.slice(0,75))}</p><small>${e(i.type)}</small></button>`).join(''):'<p class="empty">没有找到对应内容。试试游戏名称或更短的关键词。</p>';document.querySelectorAll('[data-search-type]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.searchType===searchType))}
function toggleChat(open=!$('#chat-panel').hidden){if(window.togglePlayerChat){window.togglePlayerChat(open);return;}const show=!open;$('#chat-panel').hidden=!show;$('#chat-toggle').setAttribute('aria-expanded',show);if(show){renderChat();$('#chat-input').focus()}}function openChat(){toggleChat(false)}function renderChat(){const messages=db.chat.filter(m=>m.channel===channel);$('#chat-messages').innerHTML=messages.map(m=>`<div class="chat-msg ${m.user===actor().id?'mine':''}"><small>${e(name(m.user))} · ${e(m.date)}</small><div class="chat-bubble">${e(m.text)}</div></div>`).join('')||'<p class="empty">这里还没有消息。先打个招呼吧。</p>';$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;document.querySelectorAll('[data-channel]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.channel===channel));$('#chat-input').disabled=actor().status!=='active'}
document.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;let d=b.dataset;if(d.route||d.go){ev.preventDefault();gameFilter='';typeFilter='全部';go(d.route||d.go)}if(d.game){gameFilter=d.game;typeFilter='全部';if(route!=='community')go('community');else render()}if(d.filter){typeFilter=d.filter;render()}if('clearGame'in d){gameFilter='';render()}if(d.save)toggleSave(d.save);if(d.flag)flag(d.flag);if(d.delete)removePost(d.delete);if(d.confirmDelete&&canManage()){let p=managementEntry(d.confirmDelete);if(p){p.deleted=true;audit('移除资料：'+p.title);save();$('#common-dialog').close();if(route.startsWith('article/')||route.startsWith('wiki/'))go(route.startsWith('wiki/')?'wiki':'community',false);else render();toast('已移除，可在管理台恢复')}}if(d.restore&&canManage()){let p=managementEntry(d.restore);if(p){p.deleted=false;audit('恢复资料：'+p.title);save();render()}}if(d.commentDelete){let c=db.comments.find(c=>c.id===d.commentDelete);if(c&&(canManage()||c.user===actor().id)){db.comments=db.comments.filter(k=>k.id!==c.id);audit('删除评论');save();render()}}if(d.adminTab){adminTab=d.adminTab;render()}if(d.actor){const u=db.users.find(u=>u.id===d.actor);if(u){db.actor=u.id;save();$('#common-dialog').close();if(route==='admin'&&!canManage())go('home',false);else render();renderChat();toast('当前体验身份：'+roles[u.role])}}if(d.userStatus&&canAdmin()){let u=db.users.find(u=>u.id===d.userStatus);if(u&&u.id!==actor().id){u.status=u.status==='active'?'muted':'active';audit((u.status==='active'?'解除禁言：':'禁言：')+u.name);save();render()}}if(d.searchType){searchType=d.searchType;renderSearch()}if(d.searchGo){$('#search-dialog').close();if($('#common-dialog').open)$('#common-dialog').close();go(d.searchGo)}if(d.searchUser){$('#search-dialog').close();const u=db.users.find(u=>u.id===d.searchUser);if(u)modal(u.name,`<p class="form-tip">社区身份：${roles[u.role]}<br>发布的存档：${published().filter(p=>p.user===u.id).length}</p><button class="small-btn" data-action="chat">打开聊天窗口</button>`)}if(d.channel){channel=d.channel;renderChat()}if(d.close)$('#'+d.close).close();if(d.action==='preferences')openPreferences();if(d.action==='identity')openIdentity();if(d.action==='publish')openPublish();if(d.action==='search')openSearch();if(d.action==='chat'){$('#common-dialog').close();openChat()}});
document.addEventListener('change',ev=>{let t=ev.target;if(t.id==='sort-select'){sort=t.value;render()}if(t.dataset.userRole){if(!canAdmin()){toast('只有管理员能调整用户身份');return}const u=db.users.find(u=>u.id===t.dataset.userRole);if(u&&roles[t.value]){u.role=t.value;audit('调整用户身份：'+u.name+' → '+roles[t.value]);save();render();if(!canManage()&&route==='admin')go('home',false)}}});
document.addEventListener('submit',ev=>{const f=ev.target;ev.preventDefault();if(f.id==='preferences-form'){db.interests=[...new FormData(f).getAll('game')].filter(g=>games.includes(g));save();$('#common-dialog').close();gameFilter='';render();toast('推荐已按你的兴趣更新')}if(f.id==='publish-form'){if(actor().status!=='active')return;const data=new FormData(f),title=String(data.get('title')).trim(),body=String(data.get('body')).trim();if(!title||!body)return;const p={id:id('p'),game:String(data.get('game')),type:String(data.get('type')),title:title.slice(0,120),body:body.slice(0,10000),user:actor().id,author:actor().name,sample:false,date:timestamp(),rank:20,tag:'玩家发布',deleted:false,flagged:false};db.posts.unshift(p);save();$('#common-dialog').close();go('article/'+p.id);toast('你的新存档已发布')}if(f.dataset.commentForm){if(actor().status!=='active'){toast('当前身份已被禁言');return}const text=f.querySelector('textarea').value.trim();if(!text)return;db.comments.push({id:id('c'),post:f.dataset.commentForm,user:actor().id,text:text.slice(0,2000),date:timestamp()});save();render();toast('评论已保存')}if(f.id==='chat-form'){if(actor().status!=='active')return;const text=$('#chat-input').value.trim();if(!text)return;db.chat.push({id:id('m'),channel,user:actor().id,text:text.slice(0,500),date:timestamp()});save();$('#chat-input').value='';renderChat()}});
$('#open-search').onclick=()=>openSearch();$('#wiki-button').onclick=()=>go('wiki');$('#preferences-button').onclick=openPreferences;$('#role-demo').onclick=openIdentity;$('#identity-button').onclick=openIdentity;$('#my-posts').onclick=()=>{gameFilter='';typeFilter='全部';modal('我的帖子',`<div class="wiki-cards">${published().filter(p=>p.user===actor().id).map(p=>`<button class="wiki-card" data-search-go="article/${p.id}"><h3>${e(p.title)}</h3></button>`).join('')||'<p class="empty">还没有发布内容。</p>'}</div>`)};$('#site-query').oninput=renderSearch;$('#chat-toggle').onclick=()=>toggleChat();$('#party-chat').onclick=openChat;$('#chat-close').onclick=()=>toggleChat(true);
$('#rules-button').onclick=()=>modal('社区约定',`<p class="form-tip">1. 尊重玩家，讨论游戏，不攻击个人。<br>2. 剧透、MOD 和资源条目明确标注。<br>3. 分享资料时注明作者与来源，不上传未知文件。<br>4. 有疑问的资料可以由版主标记，管理员可处理用户身份。</p>`);$('#effects-button').onclick=()=>modal('让小人住在网页里',`<p class="form-tip">平面安全出口小人会在导航旁探头，在存档窗口和传送门附近互动。栏目切换采用推页、开箱和操作电脑三种局部动画，顶部导航始终保留。<br><br>保留多边形棱镜、液态金属、磁吸按钮、逐项入场、点击粒子与低保真画面。<br>支持暂停与系统减少动态效果设置。</p>`);$('#reset-button').onclick=()=>modal('重置本机演示数据',`<p class="form-tip">将清除本机新增帖子、评论、聊天、收藏及管理操作，并恢复示例内容。</p><button class="small-btn danger" id="confirm-reset">确认重置</button>`);document.addEventListener('click',ev=>{if(ev.target.closest('#confirm-reset')){db=initial();save();$('#common-dialog').close();render('home');history.replaceState(null,'','#home');renderChat();toast('演示存档已重置')}});
$('#motion-toggle').onclick=()=>{motionPaused=!motionPaused;updateChrome()};reduced.addEventListener('change',ev=>{motionPaused=ev.matches;updateChrome()});document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();if(!$('#search-dialog').open)openSearch()}if(ev.key==='Escape'&&!$('#chat-panel').hidden)toggleChat(true)});for(let d of document.querySelectorAll('dialog'))d.addEventListener('click',ev=>{if(ev.target===d){let r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close()}});function attachMagnet(){document.querySelectorAll('.small-btn,.solid-btn').forEach(b=>{if(b.dataset.magnet)return;b.dataset.magnet='1';b.addEventListener('pointermove',ev=>{if(motionPaused||reduced.matches||ev.pointerType==='touch')return;let r=b.getBoundingClientRect();b.style.setProperty('--mx',((ev.clientX-r.left)/r.width-.5)*5+'px');b.style.setProperty('--my',((ev.clientY-r.top)/r.height-.5)*3+'px')});b.addEventListener('pointerleave',()=>{b.style.setProperty('--mx','0px');b.style.setProperty('--my','0px')})})}document.addEventListener('click',ev=>{if(motionPaused||reduced.matches||ev.detail===0||!ev.target.closest('button'))return;for(let i=0;i<4;i++){const dot=document.createElement('i');dot.className='spark';dot.style.left=ev.clientX+'px';dot.style.top=ev.clientY+'px';document.body.append(dot);let a=i*Math.PI/2;dot.animate([{translate:'0 0',opacity:.6},{translate:Math.cos(a)*17+'px '+Math.sin(a)*17+'px',opacity:0}],{duration:500,easing:'ease-out'}).finished.then(()=>dot.remove())}});
window.addEventListener('popstate',()=>go(location.hash.slice(1)||'home',false));window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'home';if(r!==route)go(r)});$('#effects-button').onclick=()=>modal('本页正在使用的动效',`<p class="form-tip">多边形棱镜和流麻液态金属铺在全站低对比度背景中，随栏目切换。<br><br>Spotlight Card 用于新闻、折扣与 Wiki 卡片；Glare Hover 用于折扣卡；Star Border 用于发布按钮；Decrypted Text 用于页面标题；Animated Content 用于帖子与新闻逐项出现；Pixel Swap 用于二创转场；Magnet、Click Spark 与 Noise 分别用于按钮、点击反馈和全站复古质感。<br><br>五个主栏目分别使用报纸翻页、双人对话、坐姿敲电脑、画笔涂抹和购物袋折扣转场。</p>`);render(location.hash.slice(1)||'home');
